<script lang="ts">
  import type {WorkPackageEntityContext} from '../../lib/model/entityTypes.ts';
  import {deterministicDeliveryBranch} from '../../lib/deliveryWorkspace.ts';
  import type {DeliveryContextProjection} from '../../lib/deliveryContextProjection.ts';
  export let context:WorkPackageEntityContext;
  export let repository='UNAVAILABLE';
  export let projection:DeliveryContextProjection|null=null;
  $: branch=projection?.branch??deterministicDeliveryBranch(context.id);
  $: baseSha=projection?.head_sha??context.runtime?.startingHeadSha??'NOT_AVAILABLE';
  $: worktree=projection?.delivery_context_id??'NOT_AVAILABLE';
</script>
<section class="delivery-context-panel" data-testid="delivery-context-panel"><div class="section-label"><span>Delivery</span><small>Runtime Projection</small></div><div class="delivery-context-grid"><div><span>Delivery Context</span><code>{projection?.delivery_context_id??'NOT_AVAILABLE'}</code></div><div><span>Worktree</span><code>{projection?worktree:'NOT_AVAILABLE'}</code></div><div><span>Branch</span><code>{branch}</code></div><div><span>Repository</span><code>{projection?.repository??repository}</code></div><div><span>Commit / HEAD</span><code>{projection?.commit_sha??baseSha}</code></div><div><span>Provider</span><strong>{projection?.provider??'NOT_AVAILABLE'}</strong></div><div><span>PR</span><strong>{projection?.pr?`#${projection.pr.number} · ${projection.pr.state}`:'NOT_AVAILABLE'}</strong></div><div><span>PR HEAD</span><code>{projection?.pr?.head_sha??'NOT_AVAILABLE'}</code></div></div><div class="delivery-review-row"><span>Review</span><strong>{projection?.review.state??'NOT_AVAILABLE'}</strong><code>{projection?.review.provider??'NOT_AVAILABLE'} · {projection?.review.execution_id??'NOT_AVAILABLE'} · {projection?.review.currentness??'NOT_AVAILABLE'}</code><code>HEAD: {projection?.review.head_sha??'NOT_AVAILABLE'}</code></div><div class="delivery-review-row"><span>CI</span><strong>{projection?.ci.state??'NOT_AVAILABLE'}</strong><code>{projection?.ci.provider??'NOT_AVAILABLE'} · {projection?.ci.execution_id??'NOT_AVAILABLE'} · {projection?.ci.currentness??'NOT_AVAILABLE'}</code><code>HEAD: {projection?.ci.head_sha??'NOT_AVAILABLE'} · Result: {projection?.ci.result===null?'NOT_AVAILABLE':JSON.stringify(projection?.ci.result)}</code></div><div class="delivery-review-row"><span>Owner UAT</span><strong>{projection?.ownerUat.state??'NOT_AVAILABLE'}</strong><code>{projection?.ownerUat.reason??'No projection facts'}</code></div><p class="delivery-context-note">当前 HEAD：{projection?.head_sha??'NOT_AVAILABLE'}</p></section>
